# Validate inputs
for arr in (logp_with_result, logp_call_only, logp_no_call):
    if not isinstance(arr, np.ndarray):
        raise ValueError("Inputs must be numpy arrays.")
    if arr.ndim != 2:
        raise ValueError("Inputs must be 2D matrices.")
    if arr.shape[0] == 0 or arr.shape[1] == 0:
        raise ValueError("Inputs must not be empty.")
    if not np.all(np.isfinite(arr)):
        raise ValueError("Inputs must be finite.")
    if np.any(arr > 0):
        raise ValueError("Inputs must be nonpositive.")
if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
    raise ValueError("All input matrices must have the same shape.")
if isinstance(tau_filter, bool):
    raise ValueError("tau_filter must not be a boolean.")
try:
    tau_f = float(tau_filter)
except (TypeError, ValueError):
    raise ValueError("tau_filter must be a finite nonnegative float.")
if np.isnan(tau_f) or np.isinf(tau_f) or tau_f < 0:
    raise ValueError("tau_filter must be finite nonnegative.")

n_candidates, horizon = logp_with_result.shape
raw_weights = np.maximum(0, 1 - 0.2 * np.arange(horizon))
weights = raw_weights / raw_weights.sum()
L_plus = -np.sum(logp_with_result * weights, axis=1)
L_call_only = -np.sum(logp_call_only * weights, axis=1)
L_no_call = -np.sum(logp_no_call * weights, axis=1)
L_minus = np.minimum(L_no_call, L_call_only)
margins = L_minus - L_plus
keep_mask = margins >= tau_f
return keep_mask, margins
